def __post_init__(self) -> None:
        if any(
            type(rank) is not int or rank < 0
            for rank in (self.world_rank, self.role_rank)
        ):
            raise ValueError("HCCL diagnostic ranks must be nonnegative integers")

def __post_init__(self) -> None:
        if (
            type(self.layer_indices) is not tuple
            or not self.layer_indices
            or any(type(layer) is not int or layer < 0 for layer in self.layer_indices)
            or any(
                left >= right
                for left, right in zip(
                    self.layer_indices, self.layer_indices[1:], strict=False
                )
            )
        ):
            raise ValueError(
                "HCCL diagnostic layers must be ordered nonnegative indices"
            )
        if self.actual_compute_stream not in ("parent", "compute"):
            raise ValueError("HCCL diagnostic actual compute stream is unsupported")
        if (
            self.diagnostics.selection.phase == "eager"
            and self.actual_compute_stream != "parent"
        ):
            raise ValueError(
                "current eager diagnostics require actual serial parent streams"
            )
        if type(self.in_profile_run) is not bool or type(self.is_warmup) is not bool:
            raise ValueError("HCCL diagnostic profile/warmup markers must be bool")
        if self.compute_sync_active and self.diagnostics.synchronize is None:
            raise ValueError(
                "active FFN compute-sync diagnostics require a synchronizer"
            )

def ffn_compute_sync_diagnostics(self) -> bool:
        return (
            self.role == "ffn"
            and self.phase == "eager"
            and self.num_stages == 1
            and self.settings.ffn_compute_sync_diagnostics
        )

def diagnostic_record(self) -> dict[str, str | int | bool]:
        """Export fresh configured, logical and physical values outside capture."""
        return {
            "role": self.role,
            "phase": self.phase,
            "num_stages": self.num_stages,
            **{
                f"configured.{name}": value
                for name, value in self.settings.effective_settings().items()
            },
            **{
                f"effective.{name}": value
                for name, value in self.effective_settings().items()
            },
            "logical.compute_stream": self.logical_compute_stream,
            "logical.send_stream": self.logical_send_stream,
            "logical.recv_stream": self.logical_recv_stream,
            "physical.compute_stream": self.physical_compute_stream,
            "physical.send_stream": self.physical_send_stream,
            "physical.recv_stream": self.physical_recv_stream,
            "parent_transport_override": self.parent_transport_override,
        }

def post_ffn_receive(self, layer_idx: int, stage_idx: int) -> HcclFFNTicket:
        self._active("ffn")
        slot = self._step(layer_idx, stage_idx)
        if slot.ticket is not None and not slot.output_posted:
            raise RuntimeError("post the current FFN output before the next receive")
        try:
            self._release(slot)
            ticket = HcclFFNTicket(layer_idx, stage_idx)
            slot.ticket = ticket
            peer = self.plan.stages[stage_idx].for_ffn(self.transport.role_rank)[0]
            with use_npu_current_stream(self.receive_stream):
                if slot.reuse_ready is not None:
                    slot.reuse_ready.wait(self.receive_stream)
                self._retain(slot.tensors, self.receive_stream)
                for tensor in (
                    slot.inputs.hidden_states,
                    slot.inputs.hidden_states_fp32,
                    slot.inputs.input_ids,
                ):
                    slot.works.append(
                        dist.irecv(
                            tensor,
                            group=self.transport.data_groups[stage_idx],
                            group_src=peer.attention_world_rank,
                        )
                    )
            return ticket
        except BaseException:
            self.fail()
            raise

def finish(self) -> None:
        self._active()
        if self._posted != len(self._steps) or any(
            slot.ticket is not None
            and (
                slot.loaned
                or not slot.consumed
                or (self.transport.role == "ffn" and not slot.output_posted)
            )
            for slot in self._slots.values()
        ):
            raise RuntimeError(
                "finish requires all postings and closed native consumer loans"
            )
        try:
            for slot in self._slots.values():
                self._release(slot)
            self.transport._complete_eager_pipeline(self)
            self._finished = True
        except BaseException:
            self.fail()
            raise

def open_parent(self) -> HcclEagerPipeline | None:
        """Select before data posting; never switch an in-flight parent."""
        transport, plan = self.transport, self.transport.plan
        if (
            not self._initialized
            or not transport.initialized
            or transport.closed
            or transport.terminal
            or plan is None
        ):
            raise RuntimeError(
                "eager selection requires its initialized accepted parent"
            )
        selection = select_hccl_overlap(
            self.settings,
            role=transport.role,
            phase="eager",
            num_stages=len(plan.stages),
        )
        if not selection.eager_u2_stream_overlap or plan.mode != "target":
            return None
        return transport.open_eager_pipeline(
            parent_stream=self.parent_stream,
            send_stream=self.send_stream,
            receive_stream=self.receive_stream,
        )

def run_deepseek_v41_stages(
    model: AFDDeepseekV41AttentionModel,
    stages: tuple[DeepseekV41StageInputs, ...],
    contexts: tuple[ForwardContext, ...],
    token_slices: tuple[slice, ...],
    transport: HcclStagedTransport,
    *,
    pipeline: HcclEagerPipeline | None = None,
    compute_stream: torch.npu.Stream | None = None,
) -> torch.Tensor | tuple[torch.Tensor, list[torch.Tensor]]:
    # ### PATCH START: admit an explicit accepted eager parent
    plan = transport.plan
    if transport.role != "attention" or plan is None:
        raise ValueError("V4.1 stages require an accepted Attention parent plan")
    if model.use_sequence_parallel:
        raise ValueError("V4.1 stages require non-SP execution")
    layers = tuple(model.layers)
    if (
        model.start_layer != 0
        or model.end_layer != len(layers)
        or tuple(layer.layer_idx for layer in layers) != plan.layer_indices
    ):
        raise ValueError("V4.1 stages require the complete PP1 target layer plan")
    if not len(stages) == len(contexts) == len(token_slices) == len(plan.stages):
        raise ValueError("V4.1 stages must match native child contexts and plan")
    if (pipeline is None) != (compute_stream is None):
        raise ValueError("eager pipeline and compute stream must be supplied together")
    if pipeline is not None and (
        pipeline.transport is not transport
        or pipeline.plan is not plan
        or pipeline.finished
        or pipeline.failed
        or compute_stream.device != pipeline.parent_stream.device
        or torch.npu.current_stream(pipeline.parent_stream.device)
        != pipeline.parent_stream
    ):
        raise ValueError("eager stages require their active exact parent and streams")
    bindings = DeepseekV41StageAttentionStates(model, token_slices)
    for stage_idx, (stage, context, token_slice) in enumerate(
        zip(stages, contexts, token_slices, strict=True)
    ):
        rows = plan.stages[stage_idx].attention_padded_tokens[transport.role_rank]
        if (
            context.cudagraph_runtime_mode != CUDAGraphMode.NONE
            or context.ubatch_idx != stage_idx
            or stage.positions.ndim != 1
            or stage.positions.shape[0] != rows
            or stage.input_ids.shape != (rows,)
            or token_slice.stop - token_slice.start != rows
            or (
                stage.inputs_embeds is not None and stage.inputs_embeds.shape[0] != rows
            )
        ):
            raise ValueError("V4.1 native child coordinates do not match the plan")
        if model.has_engram and (
            stage.engram.mask.shape != (rows,)
            or any(lookup.shape[0] != rows for lookup in stage.engram.lookups.values())
            or any(
                layer.engram is not None and layer.layer_idx not in stage.engram.lookups
                for layer in layers
            )
        ):
            raise ValueError("V4.1 Engram inputs must be parent token views")

    if pipeline is not None:
        # The native parent prepared input/metadata once. Keep its buffers
        # alive through side compute; Engram readiness is still waited at the
        # native first consumer rather than synchronizing its producer here.
        ready = torch.npu.Event()
        ready.record(pipeline.parent_stream)
        ready.wait(compute_stream)
        parent_state = model.shared_attention_state
        tensors = (
            parent_state.topk_indices,
            parent_state.candidates,
            parent_state.candidate_lengths,
            parent_state.topk_lengths,
            model._mtp_hidden_buffer,
        )
        for tensor in tensors:
            if tensor is not None:
                tensor.record_stream(compute_stream)
        for stage in stages:
            for tensor in (
                stage.input_ids,
                stage.positions,
                stage.engram.mask,
                *stage.engram.lookups.values(),
            ):
                tensor.record_stream(compute_stream)
            if stage.inputs_embeds is not None:
                stage.inputs_embeds.record_stream(compute_stream)

    executions = []
    for stage_idx, (stage, context) in enumerate(zip(stages, contexts, strict=True)):
        with (
            override_forward_context(context),
            use_npu_current_stream(compute_stream)
            if compute_stream is not None
            else nullcontext(),
        ):
            if stage.inputs_embeds is not None:
                hidden_states = stage.inputs_embeds
            elif stage.input_ids.numel():
                hidden_states = model.embed_input_ids(stage.input_ids)
            else:
                hidden_states = stage.positions.new_empty(
                    (0, model.config.hidden_size), dtype=torch.bfloat16
                )
            if hidden_states.dtype != torch.bfloat16:
                raise ValueError("V4.1 staged HCCL requires BF16 activations")
            hidden_states = hidden_states.unsqueeze(1).repeat(1, model.hc_mult, 1)
            pre_mix = hidden_states.new_zeros(
                hidden_states.shape[0], model.hc_mult, dtype=torch.float32
            )
            pre_mix[:, 0] = 1.0
            ids = stage.input_ids.to(dtype=torch.int32).clone()
            ids[
                plan.stages[stage_idx].attention_valid_tokens[transport.role_rank] :
            ] = 0
            executions.append(
                _StageExecution(
                    hidden_states, pre_mix, ids, stage.engram.mask_ready_event, []
                )
            )
    # ### PATCH END: admit an explicit accepted eager parent

    # ### PATCH START: layer-major replaces native full-stage model calls
    if pipeline is not None:
        _run_pipelined_stages(
            model,
            layers,
            stages,
            contexts,
            executions,
            bindings,
            pipeline,
            compute_stream,
        )
    else:
        for layer in layers:
            for stage_idx, (stage, context, execution) in enumerate(
                zip(stages, contexts, executions, strict=True)
            ):
                with override_forward_context(context), bindings.bind(stage_idx):
                    x, x_fp32, continuation = _prepare_stage(
                        model, layer, stage, execution
                    )
                    if any(plan.stages[stage_idx].attention_padded_tokens):
                        transport.send_layer_inputs(
                            layer.layer_idx,
                            stage_idx,
                            x.contiguous(),
                            x_fp32.contiguous(),
                            execution.transfer_ids,
                        )
                        ffn_output = transport.receive_layer_output(
                            layer.layer_idx, stage_idx
                        )
                        if continuation is not None:
                            execution.hidden_states, execution.pre_mix = (
                                layer.complete_remote_ffn(ffn_output, continuation)
                            )
    # ### PATCH END: layer-major replaces native full-stage model calls

    # ### PATCH START: reconstruct parent coordinates before final native collapse
    hidden_states = torch.cat(
        [execution.hidden_states for execution in executions], dim=0
    )
    pre_mix = torch.cat([execution.pre_mix for execution in executions], dim=0)
    if model._mtp_hidden_buffer is not None:
        model._mtp_hidden_buffer[: hidden_states.shape[0]].copy_(
            hidden_states.flatten(1)
        )
    if hidden_states.shape[0]:
        hidden_states = layers[-1].hc_collapse(hidden_states, pre_mix)
        hidden_states = model.norm(hidden_states)
    else:
        hidden_states = hidden_states.new_empty((0, model.config.hidden_size))
    aux_hidden_states = [
        torch.cat([execution.auxiliary[index] for execution in executions], dim=0)
        for index in range(len(executions[0].auxiliary))
    ]
    # ### PATCH END: reconstruct parent coordinates before final native collapse
    if aux_hidden_states:
        return hidden_states, aux_hidden_states
    return hidden_states

def _run_pipelined_stages(
    model: AFDDeepseekV41AttentionModel,
    layers: tuple[AFDDeepseekV41AttentionDecoderLayer, ...],
    stages: tuple[DeepseekV41StageInputs, ...],
    contexts: tuple[ForwardContext, ...],
    executions: list[_StageExecution],
    bindings: DeepseekV41StageAttentionStates,
    pipeline: HcclEagerPipeline,
    compute_stream: torch.npu.Stream,
) -> None:
    # ### PATCH START: delayed HC consumers with bounded eager wire tickets
    try:
        for layer_index, layer in enumerate(layers):
            for stage_idx, (stage, context, execution) in enumerate(
                zip(stages, contexts, executions, strict=True)
            ):
                if execution.ticket is not None:
                    with (
                        override_forward_context(context),
                        bindings.bind(stage_idx),
                        pipeline.attention_output(
                            execution.ticket,
                            consumer_stream=compute_stream,
                            retain=_continuation_tensors(execution),
                        ) as output,
                    ):
                        if execution.continuation is not None:
                            execution.hidden_states, execution.pre_mix = layers[
                                layer_index - 1
                            ].complete_remote_ffn(output, execution.continuation)
                    execution.ticket = execution.continuation = None
                with (
                    override_forward_context(context),
                    bindings.bind(stage_idx),
                    use_npu_current_stream(compute_stream),
                ):
                    x, fp32, execution.continuation = _prepare_stage(
                        model, layer, stage, execution
                    )
                    x, fp32 = x.contiguous(), fp32.contiguous()
                if any(pipeline.plan.stages[stage_idx].attention_padded_tokens):
                    execution.ticket = pipeline.post_attention(
                        layer.layer_idx,
                        stage_idx,
                        x,
                        fp32,
                        execution.transfer_ids,
                        producer_stream=compute_stream,
                        retain=_continuation_tensors(execution),
                    )
        for stage_idx, (context, execution) in enumerate(
            zip(contexts, executions, strict=True)
        ):
            if execution.ticket is None:
                continue
            with (
                override_forward_context(context),
                bindings.bind(stage_idx),
                pipeline.attention_output(
                    execution.ticket,
                    consumer_stream=compute_stream,
                    retain=_continuation_tensors(execution),
                ) as output,
            ):
                if execution.continuation is not None:
                    execution.hidden_states, execution.pre_mix = layers[
                        -1
                    ].complete_remote_ffn(output, execution.continuation)
            execution.ticket = execution.continuation = None
        # Collapse/MTP/native retirement must see all stage computations. A
        # device dependency plus allocator ownership replaces a host sync here.
        done = torch.npu.Event()
        done.record(compute_stream)
        done.wait(pipeline.parent_stream)
        for execution in executions:
            for tensor in _continuation_tensors(execution):
                tensor.record_stream(pipeline.parent_stream)
    except BaseException:
        pipeline.fail()
        raise

def _execute_hccl_v41_parent(
    model: AFDDeepseekV41AttentionForCausalLM,
    model_state: EngramModelState,
    model_inputs: dict[str, Any],
    contexts: tuple[ForwardContext, ...],
    token_slices: tuple[slice, ...],
    transport: HcclStagedTransport,
    *,
    engram_prepared: bool,
    eager_pipeline: HcclEagerPipeline | None,
    compute_stream: torch.npu.Stream | None,
) -> torch.Tensor | tuple[torch.Tensor, list[torch.Tensor]]:
    try:
        parent_context = get_forward_context()
        if (
            parent_context.cudagraph_runtime_mode != CUDAGraphMode.NONE
            or model_inputs.get("engram_graph_events", False)
            or model_inputs.get("intermediate_tensors") is not None
        ):
            raise ValueError("V4.1 staged HCCL run requires an eager PP1 parent")
        if not isinstance(model_state, EngramModelState):
            raise ValueError("V4.1 staged HCCL requires the native Engram ModelState")
        if model_state._cg_mode != CUDAGraphMode.NONE:
            raise ValueError("V4.1 staged HCCL requires prepared eager Engram mode")
        if transport.role != "attention" or transport.plan is None:
            raise ValueError("V4.1 staged HCCL requires an accepted Attention plan")
        parent_inputs = dict(model_inputs)
        # Native prepare_inputs already built the full parent's lookback
        # and pending producer. Run it here once, in the parent context;
        # bypassing nn.Module.__call__ avoids its per-model pre-hook.
        if not engram_prepared:
            parent_inputs.update(model_state.prepare_engram())
        if parent_inputs.get("engram_graph_events", False):
            raise ValueError("V4.1 staged HCCL does not consume Graph Engram events")
        if not model.language_model.model.has_engram:
            parent_inputs.setdefault("engram_lookups", {})
            parent_inputs.setdefault(
                "engram_mask",
                parent_inputs["positions"].new_empty(0, dtype=torch.bool),
            )
        engram = DeepseekV41EngramInputs(
            parent_inputs["engram_lookups"],
            parent_inputs["engram_mask"],
            parent_inputs.get("engram_pending"),
            parent_inputs.get("engram_mask_ready_event"),
        )
        slices = token_slices
        if not slices or slices[-1].stop != parent_inputs["positions"].shape[0]:
            raise ValueError("V4.1 child slices must cover the parent padded tokens")
        stages = []
        for token_slice in slices:
            child = slice_model_inputs(parent_inputs, token_slice)
            if child["input_ids"] is None:
                raise ValueError("V4.1 staged HCCL requires native raw token IDs")
            stages.append(
                DeepseekV41StageInputs(
                    child["input_ids"],
                    child["positions"],
                    engram.slice(token_slice),
                    child.get("inputs_embeds"),
                )
            )
        schedule = (
            {"pipeline": eager_pipeline, "compute_stream": compute_stream}
            if eager_pipeline is not None or compute_stream is not None
            else {}
        )
        output = run_deepseek_v41_stages(
            model.language_model.model,
            tuple(stages),
            contexts,
            slices,
            transport,
            **schedule,
        )
        if eager_pipeline is None:
            transport.finish_forward()
        else:
            eager_pipeline.finish()
        return output
    except BaseException:
        # A peer can already be waiting on payload/COMPLETE. Mark this
        # endpoint terminal without blocking on an unsolicited error send;
        # backend timeout/process supervision owns failed peer unwinding.
        transport.terminal = True
        if eager_pipeline is not None:
            eager_pipeline.fail()
        raise

def install_context(self, context: ForwardContext) -> None:
        # KV maintenance has no model call. Child contexts are constructed by
        # the native runner's imported alias and have no parent descriptor.
        if context.batch_descriptor is None:
            return
        if self.parent_context is not None:
            raise RuntimeError("one native execution must create one parent context")
        if context.cudagraph_runtime_mode != CUDAGraphMode.NONE:
            raise ValueError("staged native execution requires an eager parent")
        self.parent_context = context
        if self.local is None:
            self.local = HcclLocalForward(
                self.mode,
                (self.valid_tokens,),
                (int(context.batch_descriptor.num_tokens),),
            )
        transaction_id = None
        if self.transport.negotiated_capabilities.graph_execution_version:
            decision = self.transport.graph_reservation
            if decision is None or decision.phase != "eager":
                raise ValueError(
                    "native eager execution requires its eager reservation"
                )
            if self.transport.is_coordinator:
                transaction_id = decision.transaction_id
        elif self.transport.is_coordinator:
            self.owner._afd_transaction_counter += 1
            transaction_id = f"native-{self.owner._afd_transaction_counter}"
        plan = self.transport.submit_forward(self.local, transaction_id=transaction_id)
        if plan is None:
            raise RuntimeError("staged session stopped before native forward")
        if self.prepared is None:
            if context.additional_kwargs is None:
                context.additional_kwargs = {}
            context.additional_kwargs[HCCL_V41_PARENT_FORWARD_KEY] = self

def run(self) -> None:
        """Execute/record tensor work; replay does not enter this Python loop."""
        bank, pipeline, progress = self.bank, self.pipeline, self.diagnostics
        with pipeline.run() if pipeline is not None else nullcontext():
            for layer_idx in bank.layer_indices:
                for stage_idx, (rows, context) in enumerate(
                    zip(bank.stage_rows, self.contexts, strict=True)
                ):
                    if not rows:
                        continue
                    with override_forward_context(context):
                        _set_moe_layer_index(context, layer_idx)
                        if progress is not None:
                            progress.record("recv_begin", layer_idx, stage_idx)
                        with (
                            pipeline.ffn_receive(layer_idx, stage_idx)
                            if pipeline is not None
                            else nullcontext()
                        ):
                            buffers = bank.receive_inputs(stage_idx)
                        if progress is not None:
                            progress.record("recv_returned", layer_idx, stage_idx)
                            progress.record("compute_begin", layer_idx, stage_idx)
                        with (
                            pipeline.compute(
                                layer_idx,
                                stage_idx,
                                inputs=(
                                    buffers.hidden_states,
                                    buffers.hidden_states_fp32,
                                    buffers.input_ids,
                                ),
                            )
                            if pipeline is not None
                            else nullcontext()
                        ):
                            output = self.model.compute_ffn_output(
                                hidden_states=buffers.hidden_states,
                                layer_idx=layer_idx,
                                input_ids=buffers.input_ids,
                                hidden_states_fp32=buffers.hidden_states_fp32,
                                already_sequence_parallel=False,
                            )
                        if progress is not None:
                            progress.record("compute_returned", layer_idx, stage_idx)
                            progress.record("send_begin", layer_idx, stage_idx)
                        with (
                            pipeline.ffn_send(layer_idx, stage_idx, tensors=(output,))
                            if pipeline is not None
                            else nullcontext()
                        ):
                            bank.send_output(stage_idx, output)
                        if progress is not None:
                            progress.record("send_returned", layer_idx, stage_idx)
                if pipeline is not None and not pipeline.policy.ffn_cross_layer:
                    if progress is not None:
                        progress.record("layer_send_wait_begin", layer_idx, 0)
                    pipeline.join_layer(layer_idx)
                    if progress is not None:
                        progress.record("layer_send_wait_returned", layer_idx, 0)
            if pipeline is not None:
                if progress is not None:
                    progress.record("final_send_wait_begin", bank.layer_indices[-1], 0)
                pipeline.join()
                if progress is not None:
                    progress.record(
                        "final_send_wait_returned", bank.layer_indices[-1], 0
                    )

def _diagnostics(
        self, selection: HcclOverlapSelection | None
    ) -> HcclStageDiagnostics | None:
        if selection is None or not (
            selection.settings.stage_diagnostics
            or selection.settings.ffn_compute_sync_diagnostics
        ):
            return None
        return HcclStageDiagnostics(
            selection,
            world_rank=self.transport.world_rank,
            role_rank=self.transport.role_rank,
            emit=self._diagnostic_sink,
            synchronize=partial(torch.npu.synchronize, self.runner.device),
        )

def execute_step(self) -> bool:
        """Serve one parent; acknowledged idle STOP returns False.

        Recording a capture does not execute or validate its arithmetic. The
        accepted capture phase still retires its host parent after publication;
        later replay performs device work. No device failure retries as eager.
        """
        try:
            self._validate_binding()
            with set_current_vllm_config(self.runner.vllm_config):
                decision = self.transport.receive_graph_reservation(self._resolve)
                if decision is None:
                    self._acknowledged_stop = True
                    return False
                plan = self.transport.receive_forward()
                if plan is None:
                    raise RuntimeError(
                        "FFN graph session stopped inside a reserved parent"
                    )
                if decision.phase == "eager":
                    selection = (
                        select_hccl_overlap(
                            self.overlap_settings,
                            role="ffn",
                            phase="eager",
                            num_stages=len(plan.stages),
                        )
                        if self.overlap_settings is not None
                        else None
                    )
                    diagnostics = self._diagnostics(selection)
                    if diagnostics is None:
                        execute_hccl_v41_parent(self.runner, self.transport)
                    else:
                        execute_hccl_v41_parent(
                            self.runner, self.transport, diagnostics=diagnostics
                        )
                    return True
                generation = self._reserved_generation
                if generation is None or generation != self._generation():
                    raise ValueError("FFN graph storage changed after reservation")
                assert decision.key is not None
                if decision.phase == "replay":
                    entry = self.cache.find(decision.key, generation)
                    if entry is None:
                        raise ValueError(
                            "FFN graph readiness changed after reservation"
                        )
                    self._validate_resources(entry.resources)
                    entry.resources.bank.update_counts(plan)
                    entry.graph.replay()
                else:
                    resources = self._prepare_resources(plan)
                    if generation != self._generation():
                        raise ValueError("FFN graph storage changed during preparation")
                    if decision.phase == "warmup":
                        resources.body.run()
                    else:
                        graph = self.graph_factory()
                        self._active_graph = graph
                        self.cache.reserve_capture(
                            decision.key, generation, graph, resources
                        )
                        with self.graph_capture(graph):
                            resources.body.run()
                        if generation != self._generation():
                            raise ValueError("FFN graph storage changed during capture")
                        self.cache.publish_capture(decision.key, generation)
                if generation != self._generation():
                    raise ValueError("FFN graph storage changed during graph phase")
                self.transport.complete_graph_forward(decision.key)
                self._active_bank = self._active_resources = self._active_graph = None
                self._active_contexts = []
                return True
        except BaseException:
            self._failed = True
            self.transport.terminal = True
            self.cache.fail()
            raise

def execute_hccl_v41_step(self, transport: HcclStagedTransport) -> bool:
        """Receive and execute one v3 parent; False means acknowledged peer STOP.

        The worker owns transport initialization, shutdown and error reporting.
        No legacy connector plan or native scheduler participates in this path.
        """
        if transport.role != "ffn":
            raise ValueError("V4.1 service requires an FFN transport")
        try:
            if transport.negotiated_capabilities.graph_execution_version == 1:
                service = self.hccl_v41_graph_service
                if service is None:
                    raise RuntimeError("FFN graph service has not been bound")
                if service.runner is not self or service.transport is not transport:
                    raise ValueError("FFN graph execution requires its bound session")
                return service.execute_step()
            session = self.hccl_v41_eager_session
            if session is not None and session.transport is not transport:
                raise ValueError("FFN eager execution requires its bound session")
            if transport.receive_forward() is None:
                return False
            pipeline = None if session is None else session.open_parent()
            if pipeline is None:
                execute_hccl_v41_parent(self, transport)
            else:
                execute_hccl_v41_eager_parent(
                    self, transport, pipeline, compute_stream=session.compute_stream
                )
            return True
        except BaseException:
            transport.terminal = True
            raise
